import {DotLottie} from '../../vendor/dotlottie-web.js';
import {IconController} from './controller.mjs';
DotLottie.setWasmUrl(new URL('../../vendor/dotlottie-player.wasm',import.meta.url).href);
const reduced=matchMedia('(prefers-reduced-motion: reduce)'),cards=[],references=[];
const hint=document.querySelector('#hint'),sequenceButton=document.querySelector('#sequence'),loopButton=document.querySelector('#loop');
let theme='dark',style='outline',weight=2,speed=1,sequence=0,looping=false;
function paint(p){p.setTheme(theme);for(const [name,w]of [['light',1.5],['regular',2],['bold',2.5]])p.setScalarSlot('style.outline.'+name,style!=='solid'&&weight===w?100:0);p.setScalarSlot('style.solid',style==='solid'?100:0);p.setScalarSlot('style.tint',style==='duotone'?18:0);}
async function load(canvas,data){const p=new DotLottie({canvas,data,autoplay:false,loop:false,useFrameInterpolation:true,renderConfig:{devicePixelRatio:Math.min(devicePixelRatio||1,2),autoResize:true,freezeOnOffscreen:false}});await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(new Error('Lottie load timeout')),15000);p.addEventListener('load',()=>{clearTimeout(timer);resolve();});p.addEventListener('loadError',()=>{clearTimeout(timer);reject(new Error('Lottie load error'));});});return p;}
function stopSequence(){sequence++;looping=false;loopButton.setAttribute('aria-pressed','false');for(const c of cards)if(c.controller?.running){c.controller.cancel();c.controller.rest();}}
function updateHint(){hint.textContent=reduced.matches?'Reduced motion: state changes are immediate; acknowledgement icons stay still.':'Hover or replay a gesture. Use Confirm / Reset and Lock / Unlock to try the state changes.';sequenceButton.disabled=reduced.matches||cards.some(c=>!c.controller);loopButton.disabled=sequenceButton.disabled;}
function setTime(card){const p=card.controller.players[0];card.root.querySelector('.scrub').value=p.currentFrame;card.root.querySelector('.time').textContent=(p.currentFrame/60).toFixed(2)+' s';}
function update(card,c){
 const root=card.root;root.querySelector('.state').textContent=c.running?'Playing':c.paused?'Paused':c.icon.stateful?c.state[0].toUpperCase()+c.state.slice(1):'At rest';
 for(const b of root.querySelectorAll('[data-motion]'))b.setAttribute('aria-pressed',String(b.dataset.motion===c.profile));
 root.querySelector('.scrub').max=c.meta.frames-1;root.querySelector('.scrub').disabled=reduced.matches;
 root.querySelector('.size').textContent=(c.meta.bytes/1024).toFixed(1)+' KB';root.querySelector('.timing').textContent=c.meta.active.toFixed(2)+' s · '+(c.meta.stateful?'holds '+c.meta.endState:'gesture');
 const download=root.querySelector('.download');download.href=`assets/${c.meta.name}.lottie?v=${c.meta.sha256}`;download.setAttribute('aria-label',`Download ${c.icon.label}, ${c.profile} motion, ${c.meta.direction} action`);
 if(c.icon.stateful){const b=root.querySelector('.state-action');b.textContent=c.state===c.icon.endState?c.icon.reverseLabel:c.icon.forwardLabel;b.disabled=c.running;}
 if(card.controller)setTime(card);
}
async function mount(icon){
 const root=document.createElement('article');root.className='card';root.dataset.icon=icon.name;
 root.innerHTML=`<div class="card-head"><span class="index">${icon.number}</span><h2>${icon.label}</h2><span class="state" role="status">Loading…</span></div><div class="motion" role="group" aria-label="${icon.label} motion"><button disabled data-motion="light" aria-pressed="true">Light motion</button><button disabled data-motion="strong" aria-pressed="false">Strong motion</button></div><button disabled class="stage" aria-label="Replay ${icon.label} demo"><canvas width="144" height="144" role="img" aria-label="${icon.label} animated icon"></canvas><span class="stage-label">${icon.stateful?'REPLAY DEMO ↗':'HOVER TO PLAY ↗'}</span></button><div class="card-info"><h3>${icon.heading}</h3><p>${icon.description}</p></div><div class="actions"><button disabled class="replay">Replay${icon.stateful?' demo':''}</button>${icon.stateful?'<button disabled class="state-action"></button>':''}<a class="download" download>Download ↓</a></div><div class="timeline"><input disabled class="scrub" type="range" min="0" max="143" value="0" aria-label="${icon.label} animation progress"><span class="time">0.00 s</span></div><div class="sizes"><span>ACTUAL SIZE</span>${[24,32,48].map(size=>`<div class="sample"><canvas width="${size}" height="${size}" style="width:${size}px;height:${size}px" role="img" aria-label="${icon.label} at ${size} pixels"></canvas>${size} px</div>`).join('')}</div><div class="card-foot"><span>.LOTTIE <span class="size"></span></span><span class="timing"></span></div>`;
 document.querySelector('#grid').append(root);const card={root,icon};cards.push(card);
 try{const response=await fetch(`./assets/${icon.name}.lottie?v=${icon.sha256}`,{cache:'no-store'});if(!response.ok)throw new Error('Asset load failed');const data=await response.arrayBuffer(),results=await Promise.allSettled([...root.querySelectorAll('canvas')].map(canvas=>load(canvas,data)));const players=results.filter(r=>r.status==='fulfilled').map(r=>r.value);if(results.some(r=>r.status==='rejected')){players.forEach(p=>p.destroy());throw new Error('Player load failed');}
  const controller=new IconController(icon,players,{paint,reduced:reduced.matches,change:c=>update(card,c)});card.controller=controller;controller.setSpeed(speed);for(const b of root.querySelectorAll("button"))b.disabled=false;controller.notify();setTime(card);players[0].addEventListener('frame',()=>setTime(card));
  const replay=()=>{stopSequence();controller.play('forward',{force:true});};root.querySelector('.stage').addEventListener('click',replay);root.querySelector('.replay').addEventListener('click',replay);
  if(!icon.stateful){root.querySelector('.stage').addEventListener('pointerenter',()=>{if(!controller.running)replay();});root.querySelector('.stage').addEventListener('focus',()=>{if(!controller.running)replay();});}
  if(icon.stateful)root.querySelector('.state-action').addEventListener('click',()=>{stopSequence();controller.toggle();});
  for(const b of root.querySelectorAll('[data-motion]'))b.addEventListener('click',()=>{stopSequence();controller.setMotion(b.dataset.motion);if(!icon.stateful)controller.play();});
  root.querySelector('.scrub').addEventListener('input',e=>{stopSequence();controller.scrub(Number(e.target.value));});
 }catch(e){root.querySelector('.state').textContent='Unavailable';root.classList.add('failed');for(const b of root.querySelectorAll('button,input'))b.disabled=true;console.error(e);}
}
async function family(){const root=document.createElement('aside');root.className='card family';root.setAttribute('aria-label','Existing icon family');root.innerHTML='<p class="eyebrow">PART OF THE SAME FAMILY</p><h2>Different mechanics.<br>One visual language.</h2><p>Rounded contours, clear openings, and movement shaped by what each object does.</p><div class="family-art"></div><p>The approved Heart beat stays in the family as the reference for more visible Strong motion.</p><div class="family-links"><a href="../01/">Heart & Bell ↗</a><a href="../02/">Search ↗</a></div>';document.querySelector('#grid').append(root);
 for(const [name,label,num]of [['heart','Heart','01'],['bell','Bell','01'],['search','Search','02']]){const figure=document.createElement('figure');figure.innerHTML=`<canvas width="64" height="64" role="img" aria-label="${label} family reference"></canvas><figcaption>${label}</figcaption>`;root.querySelector('.family-art').append(figure);const set=await fetch(`../${num}/assets/set.json`,{cache:'no-store'}).then(r=>r.json()),meta=set.icons.find(i=>i.name===name),data=await fetch(`../${num}/assets/${name}.lottie?v=${meta.sha256}`).then(r=>r.arrayBuffer()),player=await load(figure.querySelector('canvas'),data);paint(player);player.setFrame(meta.rest);references.push({player,rest:meta.rest});}
}
async function runSequence(loop){stopSequence();const token=sequence;looping=loop;loopButton.setAttribute('aria-pressed',String(loop));const selected=cards.filter(c=>c.controller&&(!loop||!c.icon.stateful));do{for(const card of selected){if(sequence!==token||reduced.matches)return;await card.controller.play('forward',{force:true,showcase:loop});}}while(looping&&sequence===token);}
sequenceButton.addEventListener('click',()=>runSequence(false));loopButton.addEventListener('click',()=>looping?stopSequence():runSequence(true));
for(const b of document.querySelectorAll('[data-style]'))b.addEventListener('click',()=>{style=b.dataset.style;for(const other of document.querySelectorAll('[data-style]'))other.setAttribute('aria-pressed',String(other===b));document.querySelector('#weight').disabled=style==='solid';repaint();});
function repaint(){for(const c of cards)c.controller?.repaint();for(const r of references){paint(r.player);r.player.setFrame(r.rest);}}
document.querySelector('#weight').addEventListener('change',e=>{weight=Number(e.target.value);repaint();});document.querySelector('#theme').addEventListener('click',e=>{theme=theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;e.currentTarget.textContent=theme==='dark'?'Light background':'Dark background';e.currentTarget.setAttribute('aria-pressed',String(theme==='light'));repaint();});document.querySelector('#speed').addEventListener('change',e=>{speed=Number(e.target.value);for(const c of cards)c.controller?.setSpeed(speed);});
reduced.addEventListener('change',()=>{stopSequence();for(const c of cards)c.controller?.setReduced(reduced.matches);updateHint();});document.addEventListener('visibilitychange',()=>{for(const c of cards)c.controller?.suspend(document.hidden);});addEventListener('pagehide',e=>{if(e.persisted){for(const c of cards)c.controller?.suspend(true);}else{stopSequence();for(const c of cards)c.controller?.destroy();for(const r of references)r.player.destroy();}});addEventListener('pageshow',()=>{for(const c of cards)c.controller?.suspend(false);});
try{const set=await fetch('./assets/set.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error('Set metadata load failed');return r.json();});for(const icon of set.icons)await mount(icon);await family();updateHint();}catch(e){hint.textContent='The icon set could not load.';console.error(e);}
